class Text:
 def split(self):return ['custom']
print(Text().split())

class Text:
 def split(self,sep):return ['custom',sep]
print(Text().split(','))

def run(sep):
 try:
  print('a,b'.split(sep))
 except (TypeError,ValueError) as error:
  print(type(error).__name__,str(error))
run('')
run(1)

