 def __index__(self):return 1.5
class Missing:pass
class Nil:__index__=None
for count in (1,None,1.5,Bad(),Missing(),Nil()):
 try:print('a,b,c'.split(',',count))
 except Exception as error:print(type(error).__name__)

events=[]
class Count:
 def __index__(self):
  events.append('index')
  return 1
def text():
 events.append('receiver')
 return 'a,b,c'
def sep():
 events.append('separator')
 return ','
def count():
 events.append('count-object')
 return Count()
print(text().split(sep(),count()),events)
